import { Router } from "express";
import { authenticate } from "../../common/middleware/auth.middleware.js";
import { requireApprovedMerchant } from "../../common/middleware/merchant.middleware.js";
import { authorizeRoles } from "../../common/middleware/role.middleware.js";
import { validate } from "../../common/middleware/validate.middleware.js";
import { cancelBooking, createBooking, getMerchantBookings, getMyBookings, reviewBooking, } from "./booking.controller.js";
import { createBookingSchema, reviewBookingSchema, } from "./booking.schema.js";
export const bookingRouter = Router();
bookingRouter.use(authenticate);
bookingRouter.post("/", authorizeRoles("Customer", "Reviewer"), validate(createBookingSchema), createBooking);
bookingRouter.get("/my-bookings", authorizeRoles("Customer", "Reviewer"), getMyBookings);
bookingRouter.patch("/:id/cancel", authorizeRoles("Customer", "Reviewer"), cancelBooking);
bookingRouter.get("/merchant-bookings", requireApprovedMerchant, getMerchantBookings);
bookingRouter.patch("/:id/status", requireApprovedMerchant, validate(reviewBookingSchema), reviewBooking);
